import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 1_000_000_007L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();

        int[] xOfY = new int[N + 1];
        int[] yOfX = new int[N + 1];

        for (int i = 0; i < 2 * N; i++) {
            int x = fs.nextInt();
            int y = fs.nextInt();
            xOfY[y] = x;
            yOfX[x] = y;
        }

        boolean[] visX = new boolean[N + 1];
        boolean[] visY = new boolean[N + 1];

        List<Integer> cycleSizes = new ArrayList<>();

        for (int x = 1; x <= N; x++) {
            if (visX[x]) continue;

            int curX = x;
            int len = 0;
            while (!visX[curX]) {
                visX[curX] = true;
                int y = yOfX[curX];
                visY[y] = true;
                len++;
                curX = xOfY[y];
            }
            cycleSizes.add(len);
        }

        long[] fact = new long[N + 1];
        long[] invFact = new long[N + 1];
        fact[0] = 1;
        for (int i = 1; i <= N; i++) fact[i] = fact[i - 1] * i % MOD;
        invFact[N] = modPow(fact[N], MOD - 2);
        for (int i = N; i >= 1; i--) invFact[i - 1] = invFact[i] * i % MOD;

        long ans = fact[N] * fact[N] % MOD;

        for (int s : cycleSizes) {
            long waysCycle = 2L * s % MOD * modPow(2, s - 1) % MOD;
            ans = ans * waysCycle % MOD;
            ans = ans * invFact[s] % MOD;
            ans = ans * invFact[s] % MOD;
        }

        System.out.println(ans % MOD);
    }

    static long modPow(long a, long e) {
        long r = 1;
        while (e > 0) {
            if ((e & 1) == 1) r = r * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return r;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

