import sys
from collections import defaultdict

def solve():
    MOD = 1_000_000_007
    input_data = sys.stdin.read().split()
    idx = 0
    N = int(input_data[idx]); idx+=1
    cols = defaultdict(list)
    rows = defaultdict(list)
    for _ in range(2*N):
        x,y = int(input_data[idx]),int(input_data[idx+1]); idx+=2
        cols[x].append(y)
        rows[y].append(x)

    parent = {}
    for x in cols:
        cols[x].sort()
        for i in range(1,len(cols[x])):
            child=(x,cols[x][i]); par=(x,cols[x][i-1])
            parent[child]=par
    for y in rows:
        rows[y].sort()
        for i in range(1,len(rows[y])):
            child=(rows[y][i],y); par=(rows[y][i-1],y)
            if child not in parent:
                parent[child]=par

    children=defaultdict(list)
    roots=[]
    all_balls=[(x,y) for x in cols for y in cols[x]]
    for b in all_balls:
        if b in parent: children[parent[b]].append(b)
        else: roots.append(b)

    subtree={}
    def dfs(node):
        s=1
        for c in children[node]: s+=dfs(c)
        subtree[node]=s; return s
    for r in roots: dfs(r)

    ans=1
    for i in range(1,2*N+1): ans=ans*i%MOD
    for b in all_balls: ans=ans*pow(subtree[b],MOD-2,MOD)%MOD
    print(ans)

solve()
